package com.agacostays.payment.controller;
import com.agacostays.payment.dto.request.PaymentWebhookRequest; import com.agacostays.payment.dto.response.ApiResponse; import com.agacostays.payment.service.PaymentWebhookService; import tools.jackson.databind.json.JsonMapper; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/payments") public class PaymentWebhookController { private final PaymentWebhookService service; private final JsonMapper mapper; public PaymentWebhookController(PaymentWebhookService s,JsonMapper m){service=s;mapper=m;} @PostMapping("/webhook") public ResponseEntity<ApiResponse<Void>> webhook(@RequestBody String raw,@RequestHeader(value="X-Razorpay-Signature",required=false)String signature) throws Exception {PaymentWebhookRequest r=mapper.readValue(raw,PaymentWebhookRequest.class);service.process(r,raw,signature);return ResponseEntity.ok(ApiResponse.ok("Webhook processed",null));} @PostMapping("/webhooks/razorpay") public ResponseEntity<ApiResponse<Void>> razorpayWebhook(@RequestBody String raw,@RequestHeader(value="X-Razorpay-Signature",required=false)String signature) throws Exception {return webhook(raw,signature);} }
